package io.github.ssfuisu.goodbyedpi.proxy

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.ByteArrayOutputStream
import java.io.OutputStream
import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.Proxy
import java.net.ServerSocket
import java.net.Socket
import kotlin.concurrent.thread

class DesyncTest {

    // ClientHello for "blocked.example.org" generated by OpenSSL.
    private val hello = "".chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    private val host = "blocked.example.org"

    /** Records every write() call separately. */
    private class Recorder : OutputStream() {
        val writes = mutableListOf<ByteArray>()
        override fun write(b: Int) { writes += byteArrayOf(b.toByte()) }
        override fun write(b: ByteArray, off: Int, len: Int) { writes += b.copyOfRange(off, off + len) }
        fun all(): ByteArray = ByteArrayOutputStream().also { o -> writes.forEach { o.write(it) } }.toByteArray()
    }

    private fun parseRecords(d: ByteArray): List<ByteArray> {
        val out = mutableListOf<ByteArray>()
        var p = 0
        while (p < d.size) {
            assertEquals(0x16.toByte(), d[p])
            val len = ((d[p + 3].toInt() and 0xff) shl 8) or (d[p + 4].toInt() and 0xff)
            out += d.copyOfRange(p + 5, p + 5 + len)
            p += 5 + len
        }
        assertEquals(d.size, p)
        return out
    }

    @Test
    fun findsSni() {
        val sni = Desync.findSni(hello)
        assertNotNull(sni)
        assertEquals(host, String(hello, sni!!.first, sni.second))
    }

    @Test
    fun splitsRecordAndSegments() {
        val rec = Recorder()
        Desync.send(rec, hello, DesyncOptions(splitTls = true, splitTlsRecord = true, httpTricks = true))
        assertEquals(2, rec.writes.size)
        rec.writes.forEach { assertTrue(!String(it, Charsets.ISO_8859_1).contains(host)) }
        val records = parseRecords(rec.all())
        assertEquals(2, records.size)
        assertArrayEquals(hello.copyOfRange(5, hello.size), records[0] + records[1])
    }

    @Test
    fun noRecordSplitWhenDisabled() {
        val rec = Recorder()
        Desync.send(rec, hello, DesyncOptions(splitTls = true, splitTlsRecord = false, httpTricks = false))
        assertEquals(2, rec.writes.size)
        assertArrayEquals(hello, rec.all())
    }

    @Test
    fun incompleteRecordIsNotReframed() {
        val part = hello.copyOf(600)
        val rec = Recorder()
        Desync.send(rec, part, DesyncOptions(splitTls = true, splitTlsRecord = true, httpTricks = false))
        assertArrayEquals(part, rec.all())
    }

    @Test
    fun httpHostRewrite() {
        val req = "GET / HTTP/1.1\r\nHost: blocked.example.org\r\nAccept: */*\r\n\r\n".toByteArray()
        val rec = Recorder()
        Desync.send(rec, req, DesyncOptions(splitTls = true, splitTlsRecord = true, httpTricks = true))
        assertEquals(2, rec.writes.size)
        assertEquals(
            "GET / HTTP/1.1\r\nhoSt:blocked.example.org\r\nAccept: */*\r\n\r\n",
            String(rec.all(), Charsets.US_ASCII)
        )
    }

    @Test
    fun socksConnectRelaysDesyncedStream() {
        val echo = ServerSocket(0)
        val received = ByteArrayOutputStream()
        val t = thread {
            echo.accept().use { s ->
                val buf = ByteArray(4096)
                val inp = s.getInputStream()
                while (received.size() < hello.size + 5) {
                    val n = inp.read(buf); if (n < 0) break
                    received.write(buf, 0, n)
                }
                s.getOutputStream().write("pong".toByteArray())
            }
        }
        val server = SocksServer(
            ProxyConfig(DesyncOptions(true, true, false), DnsForwarder("127.0.0.1", false), true)
        )
        val port = server.start()
        try {
            Socket(Proxy(Proxy.Type.SOCKS, InetSocketAddress("127.0.0.1", port))).use { c ->
                c.connect(InetSocketAddress("127.0.0.1", echo.localPort), 5000)
                c.getOutputStream().write(hello)
                val reply = ByteArray(4)
                var n = 0
                while (n < 4) n += c.getInputStream().read(reply, n, 4 - n)
                assertEquals("pong", String(reply))
            }
            t.join(5000)
            val records = parseRecords(received.toByteArray())
            assertEquals(2, records.size)
            assertArrayEquals(hello.copyOfRange(5, hello.size), records[0] + records[1])
        } finally {
            server.stop()
            echo.close()
        }
    }

    @Test
    fun socksUdpAssociateRelays() {
        val echo = DatagramSocket(0, InetAddress.getByName("127.0.0.1"))
        thread {
            val b = ByteArray(1500)
            val p = DatagramPacket(b, b.size)
            echo.receive(p)
            echo.send(DatagramPacket(b, p.length, p.socketAddress))
        }
        val server = SocksServer(
            ProxyConfig(DesyncOptions(true, true, false), DnsForwarder("127.0.0.1", false), true)
        )
        val port = server.start()
        try {
            Socket("127.0.0.1", port).use { ctl ->
                val o = ctl.getOutputStream()
                val i = java.io.DataInputStream(ctl.getInputStream())
                o.write(byteArrayOf(5, 1, 0)); i.readFully(ByteArray(2))
                o.write(byteArrayOf(5, 3, 0, 1, 0, 0, 0, 0, 0, 0))
                val r = ByteArray(10).also { i.readFully(it) }
                assertEquals(0.toByte(), r[1])
                val relayPort = ((r[8].toInt() and 0xff) shl 8) or (r[9].toInt() and 0xff)

                DatagramSocket().use { u ->
                    u.soTimeout = 5000
                    val ep = echo.localPort
                    val msg = byteArrayOf(0, 0, 0, 1, 127, 0, 0, 1, (ep ushr 8).toByte(), ep.toByte()) +
                        "hello".toByteArray()
                    u.send(DatagramPacket(msg, msg.size, InetAddress.getByName("127.0.0.1"), relayPort))
                    val b = ByteArray(1500)
                    val p = DatagramPacket(b, b.size)
                    u.receive(p)
                    assertEquals("hello", String(b, 10, p.length - 10))
                    assertEquals(ep, ((b[8].toInt() and 0xff) shl 8) or (b[9].toInt() and 0xff))
                }
            }
        } finally {
            server.stop()
            echo.close()
        }
    }
}
